package raft

import (
	"encoding/json"
	"fmt"
	"runtime"
	"sort"
	"strings"
	"testing"
	"time"
)

// TestAssuranceRestoreCommittedLogsConfigurationRecovery
//
// Sourced question: when Config.RestoreCommittedLogs is enabled, does a node that
// restarts on top of its persisted stores still recover the membership configuration
// that its own log already contains?
//
// api.go starts the startup configuration scan at max(snapshotIndex, lastApplied)+1.
// restoreFromCommittedLogs() sets lastApplied to the commit index read from the log
// store before that scan runs, so every configuration entry at an index <= that
// commit index is skipped even though it is present in the node's log.
//
// The harness builds real (bootstrap -> election -> client applies -> shutdown)
// single-voter prefixes on top of a commit-tracking log store, then restarts the node
// with the same stores and a fresh in-memory FSM, once with RestoreCommittedLogs on and
// once with it off, and reports the operands of the recovery.

type assuranceEvent map[string]interface{}

func assuranceEmit(ev assuranceEvent) {
	b, err := json.Marshal(ev)
	if err != nil {
		fmt.Println(`CA_EVENT {"event":"assurance.marshal_error"}`)
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

type assuranceStores struct {
	addr   ServerAddress
	local  ServerID
	conf   *Config
	logs   *InmemCommitTrackingStore
	stable *InmemStore
	snaps  *InmemSnapshotStore
}

func assuranceWaitElected(t *testing.T, r *Raft, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

// assuranceBuildPrefix runs the pre-restart life of one node and returns the stores it
// leaves behind. applyAfterSnapshot entries are applied after the optional snapshot, and
// the optional configuration change (AddNonvoter of a peer that never connects) is made
// after that snapshot as well, so the node has a committed configuration entry above its
// newest snapshot.
func assuranceBuildPrefix(t *testing.T, withSnapshot bool, caseName string) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	// The prefix must run with the feature enabled, otherwise no commit index is ever
	// staged into the log store and the restart has nothing to read.
	conf.RestoreCommittedLogs = true
	conf.TrailingLogs = 16

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}

	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}

	for i := 0; i < 4; i++ {
		if err := r.Apply([]byte(fmt.Sprintf("pre-%d", i)), 0).Error(); err != nil {
			t.Fatalf("prefix apply failed: %v", err)
		}
	}

	if withSnapshot {
		if err := r.Snapshot().Error(); err != nil {
			t.Fatalf("prefix snapshot failed: %v", err)
		}
		// A committed configuration entry strictly above the snapshot index.
		f := r.AddNonvoter(ServerID("assurance-peer-2"), ServerAddress("assurance-peer-2-addr"), 0, 2*time.Second)
		if err := f.Error(); err != nil {
			t.Fatalf("prefix AddNonvoter failed: %v", err)
		}
		for i := 0; i < 2; i++ {
			if err := r.Apply([]byte(fmt.Sprintf("post-%d", i)), 0).Error(); err != nil {
				t.Fatalf("prefix post apply failed: %v", err)
			}
		}
	}

	// Record the persisted state before shutdown.
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	configs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}
	snapIndex, snapTerm := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":                 "assurance.prefix",
		"case":                  caseName,
		"snapshot_present":      withSnapshot,
		"snapshot_index":        snapIndex,
		"snapshot_term":         snapTerm,
		"log_last_index":        lastIndex,
		"staged_commit_index":   stagedCommit,
		"config_entries":        configs.summary,
		"last_config_index":     configs.lastIndex,
		"last_config_voters":    configs.lastVoters,
		"last_config_nonvoters": configs.lastNonvoters,
		"recording_label_count": 0,
	})

	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

type assuranceConfigScan struct {
	summary       string
	lastIndex     uint64
	lastVoters    int
	lastNonvoters int
	lastIDs       []string
}

func assuranceLogConfigEntries(logs *InmemCommitTrackingStore, lastIndex uint64) (assuranceConfigScan, error) {
	out := assuranceConfigScan{summary: ""}
	for idx := uint64(1); idx <= lastIndex; idx++ {
		var entry Log
		if err := logs.GetLog(idx, &entry); err != nil {
			return out, err
		}
		switch entry.Type {
		case LogConfiguration:
			conf := DecodeConfiguration(entry.Data)
			voters, nonvoters := assuranceSuffrageCounts(conf)
			out.summary += fmt.Sprintf("LogConfiguration@%d(servers=%d,voters=%d)", idx, len(conf.Servers), voters)
			out.lastIndex = idx
			out.lastVoters = voters
			out.lastNonvoters = nonvoters
			out.lastIDs = assuranceSortedIDs(conf)
		case LogAddPeerDeprecated, LogRemovePeerDeprecated:
			out.summary += fmt.Sprintf("DeprecatedPeers@%d", idx)
			out.lastIndex = idx
		}
	}
	return out, nil
}

func assuranceSuffrageCounts(conf Configuration) (voters, nonvoters int) {
	for _, s := range conf.Servers {
		if s.Suffrage == Voter {
			voters++
		} else {
			nonvoters++
		}
	}
	return voters, nonvoters
}

func assuranceConfigIDs(conf Configuration) string {
	out := ""
	for i, s := range conf.Servers {
		if i > 0 {
			out += ","
		}
		out += string(s.ID)
	}
	return out
}

// assuranceSortedIDs returns a comparable, order independent list of server IDs.
func assuranceSortedIDs(conf Configuration) []string {
	out := make([]string, 0, len(conf.Servers))
	for _, s := range conf.Servers {
		out = append(out, string(s.ID))
	}
	sort.Strings(out)
	return out
}

// assuranceConfigurations asks the node's main thread for its current view of the
// tracked configurations, mirroring the pattern used by takeSnapshot.
func assuranceConfigurations(r *Raft) configurations {
	fut := &configurationsFuture{}
	fut.ShutdownCh = r.shutdownCh
	fut.init()
	select {
	case r.configurationsCh <- fut:
	case <-r.shutdownCh:
		return configurations{}
	}
	if err := fut.Error(); err != nil {
		return configurations{}
	}
	return fut.configurations
}

// assuranceRunCase restarts the node on top of the stored prefix and reports what the
// recovered node does with its configuration.
func assuranceRunCase(t *testing.T, caseName string, withSnapshot, restoreCommittedLogs bool) {
	t.Helper()

	stores := assuranceBuildPrefix(t, withSnapshot, caseName)
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	logConfigs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}

	// The fresh transport keeps the node's address (and therefore its ID) stable.
	_, trans := NewInmemTransport(stores.addr)
	conf := *stores.conf
	conf.RestoreCommittedLogs = restoreCommittedLogs

	assuranceEmit(assuranceEvent{
		"event":                   "assurance.restart." + caseName,
		"case":                    caseName,
		"restore_committed_logs":  restoreCommittedLogs,
		"snapshot_present":        withSnapshot,
		"log_last_index":          lastIndex,
		"staged_commit_index":     stagedCommit,
		"log_last_config_index":   logConfigs.lastIndex,
		"log_last_config_voters":  logConfigs.lastVoters,
		"log_last_config_servers": logConfigs.lastVoters + logConfigs.lastNonvoters,
	})

	r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		assuranceEmit(assuranceEvent{
			"event":                  "assurance.outcome." + caseName,
			"case":                   caseName,
			"restore_committed_logs": restoreCommittedLogs,
			"snapshot_present":       withSnapshot,
			"new_raft_error":         err.Error(),
		})
		return
	}

	// Observation window: 1.5s is 30 election/heartbeat timeouts of this in-memory
	// configuration (HeartbeatTimeout = ElectionTimeout = 50ms).
	deadline := time.Now().Add(1500 * time.Millisecond)
	leaderObserved := false
	polls := 0
	for time.Now().Before(deadline) {
		polls++
		if r.State() == Leader {
			leaderObserved = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}

	snapIndex, _ := r.getLastSnapshot()
	lastApplied := r.AppliedIndex()
	leaderAddr, leaderID := r.LeaderWithID()

	// Ask the main thread for the configuration the node is actually tracking.
	confs := assuranceConfigurations(r)
	latestVoters, latestNonvoters := assuranceSuffrageCounts(confs.latest)
	committedVoters, committedNonvoters := assuranceSuffrageCounts(confs.committed)
	latestIDs := assuranceSortedIDs(confs.latest)
	logIDs := logConfigs.lastIDs
	sameMembership := len(latestIDs) == len(logIDs)
	if sameMembership {
		for i := range latestIDs {
			if latestIDs[i] != logIDs[i] {
				sameMembership = false
				break
			}
		}
	}

	assuranceEmit(assuranceEvent{
		"event":                      "assurance.outcome." + caseName,
		"case":                       caseName,
		"restore_committed_logs":     restoreCommittedLogs,
		"snapshot_present":           withSnapshot,
		"leader_observed":            leaderObserved,
		"final_state":                r.State().String(),
		"polls":                      polls,
		"observation_ms":             1500,
		"leader_id":                  string(leaderID),
		"leader_addr":                string(leaderAddr),
		"latest_config_index":        confs.latestIndex,
		"committed_config_index":     confs.committedIndex,
		"latest_config_voters":       latestVoters,
		"latest_config_nonvoters":    latestNonvoters,
		"latest_config_ids":          assuranceConfigIDs(confs.latest),
		"committed_config_voters":    committedVoters,
		"committed_config_ids":       assuranceConfigIDs(confs.committed),
		"snapshot_index":             snapIndex,
		"last_applied":               lastApplied,
		"commit_index":               r.CommitIndex(),
		"last_index":                 r.LastIndex(),
		"committed_config_nonvoters": committedNonvoters,
	})

	// Does the recovered configuration equal the newest configuration entry in the
	// node's own log? Both operands are reported above; this flag is the comparison.
	matches := logConfigs.lastIndex != 0 &&
		sameMembership &&
		latestVoters == logConfigs.lastVoters &&
		latestNonvoters == logConfigs.lastNonvoters
	assuranceEmit(assuranceEvent{
		"event":                          "assurance.config_recovery." + caseName,
		"case":                           caseName,
		"restore_committed_logs":         restoreCommittedLogs,
		"snapshot_present":               withSnapshot,
		"log_last_config_index":          logConfigs.lastIndex,
		"log_last_config_voters":         logConfigs.lastVoters,
		"log_last_config_nonvoters":      logConfigs.lastNonvoters,
		"log_last_config_ids":            strings.Join(logConfigs.lastIDs, ","),
		"latest_config_index":            confs.latestIndex,
		"latest_config_voters":           latestVoters,
		"latest_config_nonvoters":        latestNonvoters,
		"latest_config_ids":              strings.Join(latestIDs, ","),
		"config_matches_last_log_config": matches,
	})

	_ = r.Shutdown().Error()
}

func TestAssuranceRestoreCommittedLogsConfigurationRecovery(t *testing.T) {
	assuranceRunCase(t, "no_snapshot_restore_on", false, true)
	assuranceRunCase(t, "no_snapshot_restore_off", false, false)
	assuranceRunCase(t, "snapshot_then_config_restore_on", true, true)
	assuranceRunCase(t, "snapshot_then_config_restore_off", true, false)
}

// TestAssuranceRestoreCommittedLogsReplayCompletion
//
// Sourced question: does the startup replay performed by restoreFromCommittedLogs
// always complete? processLogs hands batches to the FSM through a buffered channel
// whose only consumer (runFSM) is started at the end of NewRaft, and the send has no
// timeout: it waits for buffer space or shutdown. So a replay that needs more batches
// than the channel can hold blocks inside NewRaft, before the consumer exists.
//
// The harness builds prefixes whose committed log is far above their (absent)
// snapshot, restarts them with and without RestoreCommittedLogs, and reports whether
// NewRaft returned and what the blocked goroutine was doing.

func assuranceBuildReplayPrefix(t *testing.T, caseName string, entries, maxAppendEntries int) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	conf.RestoreCommittedLogs = true
	// Keep the whole committed log above the snapshot: no automatic snapshot is taken,
	// so a restart replays every committed entry from index 1.
	conf.SnapshotThreshold = 1 << 30
	conf.SnapshotInterval = time.Hour
	conf.MaxAppendEntries = maxAppendEntries

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}
	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}
	for i := 0; i < entries; i++ {
		if err := r.Apply([]byte("x"), 0).Error(); err != nil {
			t.Fatalf("prefix apply %d failed: %v", i, err)
		}
	}
	staged, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	snapIndex, _ := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":               "assurance.replay_prefix",
		"case":                caseName,
		"commands_applied":    entries,
		"log_last_index":      lastIndex,
		"staged_commit_index": staged,
		"snapshot_index":      snapIndex,
		"max_append_entries":  conf.MaxAppendEntries,
		"replay_entries":      staged - snapIndex,
		"replay_batches":      (staged - snapIndex + uint64(conf.MaxAppendEntries) - 1) / uint64(conf.MaxAppendEntries),
	})
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

// assuranceStackExcerpt returns the goroutine block that mentions marker.
func assuranceStackExcerpt(text string, marker string) (string, int) {
	count := strings.Count(text, marker)
	if count == 0 {
		return "", 0
	}
	idx := strings.Index(text, marker)
	start := idx - 200
	if start < 0 {
		start = 0
	}
	end := idx + 300
	if end > len(text) {
		end = len(text)
	}
	excerpt := strings.ReplaceAll(text[start:end], "\n", " | ")
	return excerpt, count
}

type assuranceReplayResult struct {
	raft     *Raft
	err      error
	elapsed  int64
	returned bool
}

func assuranceRunReplayCase(t *testing.T, caseName string, restoreCommittedLogs bool, entries, maxAppendEntries int) {
	t.Helper()

	stores := assuranceBuildReplayPrefix(t, caseName, entries, maxAppendEntries)
	staged, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	_, trans := NewInmemTransport(stores.addr)
	conf := *stores.conf
	conf.RestoreCommittedLogs = restoreCommittedLogs

	assuranceEmit(assuranceEvent{
		"event":                  "assurance.replay_restart." + caseName,
		"case":                   caseName,
		"restore_committed_logs": restoreCommittedLogs,
		"staged_commit_index":    staged,
		"log_last_index":         lastIndex,
		"max_append_entries":     conf.MaxAppendEntries,
		"replay_entries":         staged,
	})

	const waitMS = 8000
	ch := make(chan assuranceReplayResult, 1)
	go func() {
		start := time.Now()
		r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
		ch <- assuranceReplayResult{raft: r, err: err, elapsed: time.Since(start).Milliseconds(), returned: true}
	}()

	var res assuranceReplayResult
	select {
	case res = <-ch:
	case <-time.After(waitMS * time.Millisecond):
	}

	outcome := assuranceEvent{
		"event":                  "assurance.replay_outcome." + caseName,
		"case":                   caseName,
		"restore_committed_logs": restoreCommittedLogs,
		"new_raft_returned":      res.returned,
		"wait_ms":                waitMS,
	}
	if res.returned {
		outcome["elapsed_ms"] = res.elapsed
	}
	if res.err != nil {
		outcome["new_raft_error"] = res.err.Error()
	}
	if !res.returned {
		buf := make([]byte, 1<<20)
		n := runtime.Stack(buf, true)
		excerpt, count := assuranceStackExcerpt(string(buf[:n]), "restoreFromCommittedLogs")
		outcome["stack_mentions"] = count
		outcome["blocked_excerpt"] = excerpt
	}
	assuranceEmit(outcome)

	if res.returned && res.raft != nil {
		leaderObserved := assuranceWaitElected(t, res.raft, time.Second)
		assuranceEmit(assuranceEvent{
			"event":                  "assurance.replay_leadership." + caseName,
			"case":                   caseName,
			"restore_committed_logs": restoreCommittedLogs,
			"leader_observed":        leaderObserved,
			"final_state":            res.raft.State().String(),
			"last_applied":           res.raft.AppliedIndex(),
			"commit_index":           res.raft.CommitIndex(),
		})
		_ = res.raft.Shutdown().Error()
	}
}

func TestAssuranceRestoreCommittedLogsReplayCompletion(t *testing.T) {
	const entries = 9000
	assuranceRunReplayCase(t, "large_replay_restore_on", true, entries, 64)
	assuranceRunReplayCase(t, "large_replay_restore_off", false, entries, 64)
}

// TestAssuranceRestoreCommittedLogsReplayBound
//
// Sourced question: does the completion of the startup replay track the product of the
// batch size and the channel capacity, rather than the amount of log alone? The replay
// delivers batches of at most config.MaxAppendEntries into a channel of capacity 128, so
// the number of batches is ceil(replay/MaxAppendEntries) and the bound sits at
// 128*MaxAppendEntries entries. This runs the same flag-on restart with a smaller legal
// MaxAppendEntries, once below that bound and once above it.
func TestAssuranceRestoreCommittedLogsReplayBound(t *testing.T) {
	const maxAppendEntries = 16 // bound: 128 * 16 = 2048 replayed entries
	assuranceRunReplayCase(t, "bound16_below_replay_on", true, 1500, maxAppendEntries)
	assuranceRunReplayCase(t, "bound16_above_replay_on", true, 3000, maxAppendEntries)
}

harness.source:
package raft

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"testing"
	"time"
)

// TestAssuranceStaleConfigurationCommitQuorum
//
// Sourced question (gap 98ee8dfd5fac4b84915f91ed4b094bcf-gap-1): after a node restarts
// with Config.RestoreCommittedLogs enabled, can the older configuration it recovers
// decide a commit that the committed configuration would not allow?
//
// Design: three voters A, B, C. A snapshots while {A,B,C} is committed, C is then removed
// (committed {A,B}) and further entries are committed. A restarts with the flag on, so
// its tracked configuration is the snapshot's {A,B,C}, and B is partitioned while C stays
// connected. A's majority then counts C, which the committed configuration no longer
// contains.

type assuranceMultiEvent map[string]interface{}

func assuranceMultiEmit(ev assuranceMultiEvent) {
	b, err := json.Marshal(ev)
	if err != nil {
		fmt.Println(`CA_EVENT {"event":"assurance.multi_marshal_error"}`)
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

type assuranceMultiNode struct {
	name   string
	id     ServerID
	addr   ServerAddress
	trans  *InmemTransport
	logs   *InmemCommitTrackingStore
	stable *InmemStore
	snaps  *InmemSnapshotStore
	conf   *Config
	raft   *Raft
}

func assuranceMultiNewNode(t *testing.T, name string) *assuranceMultiNode {
	t.Helper()
	addr, trans := NewInmemTransport("")
	conf := inmemConfig(t)
	conf.RestoreCommittedLogs = true
	conf.LocalID = ServerID("server-" + string(addr))
	return &assuranceMultiNode{
		name:   name,
		id:     ServerID("server-" + string(addr)),
		addr:   addr,
		trans:  trans,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
		conf:   conf,
	}
}

func assuranceMultiConfig(nodes []*assuranceMultiNode) Configuration {
	var c Configuration
	for _, n := range nodes {
		c.Servers = append(c.Servers, Server{Suffrage: Voter, ID: n.id, Address: n.addr})
	}
	return c
}

func assuranceMultiWire(nodes []*assuranceMultiNode) {
	for i, a := range nodes {
		for j, b := range nodes {
			if i == j {
				continue
			}
			a.trans.Connect(b.addr, b.trans)
		}
	}
}

func assuranceMultiLeader(nodes []*assuranceMultiNode, timeout time.Duration) *assuranceMultiNode {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		for _, n := range nodes {
			if n.raft != nil && n.raft.State() == Leader {
				return n
			}
		}
		time.Sleep(5 * time.Millisecond)
	}
	return nil
}

func assuranceMultiWaitLeader(n *assuranceMultiNode, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if n.raft.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return n.raft.State() == Leader
}

func assuranceMultiWaitNode(r *Raft, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

func assuranceMultiConfigurations(r *Raft) configurations {
	fut := &configurationsFuture{}
	fut.ShutdownCh = r.shutdownCh
	fut.init()
	select {
	case r.configurationsCh <- fut:
	case <-r.shutdownCh:
		return configurations{}
	}
	if err := fut.Error(); err != nil {
		return configurations{}
	}
	return fut.configurations
}

func assuranceMultiSortedIDs(c Configuration) string {
	out := make([]string, 0, len(c.Servers))
	for _, s := range c.Servers {
		out = append(out, string(s.ID))
	}
	sort.Strings(out)
	return strings.Join(out, ",")
}

func assuranceMultiVoters(c Configuration) int {
	v := 0
	for _, s := range c.Servers {
		if s.Suffrage == Voter {
			v++
		}
	}
	return v
}

func assuranceMultiLastIndex(n *assuranceMultiNode) uint64 {
	idx, err := n.logs.LastIndex()
	if err != nil {
		return 0
	}
	return idx
}

// assuranceMultiLogConfig finds the newest configuration entry at or below limit.
func assuranceMultiLogConfig(logs *InmemCommitTrackingStore, limit uint64) (uint64, int, string) {
	var idx uint64
	var voters int
	var ids string
	for i := uint64(1); i <= limit; i++ {
		var entry Log
		if err := logs.GetLog(i, &entry); err != nil {
			return idx, voters, ids
		}
		if entry.Type == LogConfiguration {
			c := DecodeConfiguration(entry.Data)
			idx, voters, ids = i, assuranceMultiVoters(c), assuranceMultiSortedIDs(c)
		}
	}
	return idx, voters, ids
}

func TestAssuranceStaleConfigurationCommitQuorum(t *testing.T) {
	a := assuranceMultiNewNode(t, "A")
	b := assuranceMultiNewNode(t, "B")
	c := assuranceMultiNewNode(t, "C")
	nodes := []*assuranceMultiNode{a, b, c}
	configuration := assuranceMultiConfig(nodes)

	assuranceMultiWire(nodes)
	for _, n := range nodes {
		if err := BootstrapCluster(n.conf, n.logs, n.stable, n.snaps, n.trans, configuration); err != nil {
			t.Fatalf("bootstrap %s failed: %v", n.name, err)
		}
		r, err := NewRaft(n.conf, &MockFSM{}, n.logs, n.stable, n.snaps, n.trans)
		if err != nil {
			t.Fatalf("NewRaft %s failed: %v", n.name, err)
		}
		n.raft = r
	}

	leader := assuranceMultiLeader(nodes, 5*time.Second)
	if leader == nil {
		t.Fatalf("no leader was elected")
	}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":          "assurance.multi.start",
		"leader":         leader.name,
		"a_id":           string(a.id),
		"b_id":           string(b.id),
		"c_id":           string(c.id),
		"configured_ids": assuranceMultiSortedIDs(configuration),
	})

	// Let A apply the bootstrap configuration entry, then snapshot A while {A,B,C} is the
	// committed configuration.
	if err := leader.raft.Apply([]byte("before-snapshot"), 2*time.Second).Error(); err != nil {
		t.Fatalf("pre-snapshot apply failed: %v", err)
	}
	if err := a.raft.Snapshot().Error(); err != nil {
		t.Fatalf("snapshot on A failed: %v", err)
	}
	snapIndex, snapTerm := a.raft.getLastSnapshot()
	assuranceMultiEmit(assuranceMultiEvent{
		"event":          "assurance.multi.snapshot",
		"node":           "A",
		"snapshot_index": snapIndex,
		"snapshot_term":  snapTerm,
	})

	// Remove C, which commits against {A,B}, then commit more entries.
	if err := leader.raft.RemoveServer(c.id, 0, 2*time.Second).Error(); err != nil {
		t.Fatalf("RemoveServer(C) failed: %v", err)
	}
	for i := 0; i < 3; i++ {
		if err := leader.raft.Apply([]byte(fmt.Sprintf("after-remove-%d", i)), 2*time.Second).Error(); err != nil {
			t.Fatalf("post-removal apply %d failed: %v", i, err)
		}
	}
	aStaged, _ := a.logs.GetCommitIndex()
	aLast := assuranceMultiLastIndex(a)
	removeIndex, removeVoters, removeIDs := assuranceMultiLogConfig(a.logs, aLast)
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                 "assurance.multi.removed",
		"removed_id":            string(c.id),
		"log_config_index":      removeIndex,
		"log_config_voters":     removeVoters,
		"log_config_ids":        removeIDs,
		"a_log_last_index":      aLast,
		"a_staged_commit_index": aStaged,
		"leader_after_removal":  leader.name,
	})

	// Restart A with the flag on, over the same stores, and partition B from A and C.
	if err := a.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown A failed: %v", err)
	}
	b.trans.Disconnect(a.addr)
	b.trans.Disconnect(c.addr)
	c.trans.Disconnect(b.addr)

	_, newTrans := NewInmemTransport(a.addr)
	newTrans.Connect(c.addr, c.trans)
	c.trans.Connect(a.addr, newTrans)
	newTrans.Disconnect(b.addr)

	confA := *a.conf
	confA.RestoreCommittedLogs = true
	restartedFSM := &MockFSM{}
	restarted, err := NewRaft(&confA, restartedFSM, a.logs, a.stable, a.snaps, newTrans)
	if err != nil {
		t.Fatalf("restart of A failed: %v", err)
	}
	a.raft = restarted
	a.trans = newTrans

	confs := assuranceMultiConfigurations(restarted)
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                  "assurance.multi.restart",
		"node":                   "A",
		"latest_config_index":    confs.latestIndex,
		"latest_config_voters":   assuranceMultiVoters(confs.latest),
		"latest_config_ids":      assuranceMultiSortedIDs(confs.latest),
		"committed_config_index": confs.committedIndex,
		"log_config_index":       removeIndex,
		"log_config_voters":      removeVoters,
		"log_config_ids":         removeIDs,
		"b_connected":            false,
		"c_connected":            true,
		"b_last_index":           assuranceMultiLastIndex(b),
		"c_last_index":           assuranceMultiLastIndex(c),
	})

	wonLeadership := assuranceMultiWaitNode(restarted, 5*time.Second)
	outcome := assuranceMultiEvent{
		"event":                   "assurance.multi.outcome",
		"a_became_leader":         wonLeadership,
		"a_tracked_voters":        assuranceMultiVoters(confs.latest),
		"a_tracked_ids":           assuranceMultiSortedIDs(confs.latest),
		"committed_config_voters": removeVoters,
		"committed_config_ids":    removeIDs,
		"b_connected":             false,
	}

	if wonLeadership {
		payload := []byte("stale-quorum-entry")
		future := restarted.Apply(payload, 2*time.Second)
		applyErr := future.Error()
		entryIndex := future.Index()
		time.Sleep(200 * time.Millisecond)

		var stored Log
		var entryTerm uint64
		if err := a.logs.GetLog(entryIndex, &stored); err == nil {
			entryTerm = stored.Term
		}
		var bEntry Log
		bHasEntry := b.logs.GetLog(entryIndex, &bEntry) == nil
		var cEntry Log
		cHasEntry := c.logs.GetLog(entryIndex, &cEntry) == nil

		applied := false
		for _, l := range restartedFSM.Logs() {
			if string(l) == string(payload) {
				applied = true
				break
			}
		}

		outcome["entry_index"] = entryIndex
		outcome["entry_term"] = entryTerm
		outcome["apply_error"] = applyErr
		outcome["a_commit_index"] = restarted.CommitIndex()
		outcome["a_applied_index"] = restarted.AppliedIndex()
		outcome["b_log_has_entry"] = bHasEntry
		outcome["c_log_has_entry"] = cHasEntry
		outcome["c_entry_term"] = cEntry.Term
		outcome["a_fsm_applied_payload"] = applied
		outcome["committed_config_majority_lacks_entry"] = applyErr == nil && entryTerm != 0 && !bHasEntry
	}
	assuranceMultiEmit(outcome)
}

package raft

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"testing"
	"time"
)

// TestAssuranceRestoreCommittedLogsConfigurationRecovery
//
// Sourced question: when Config.RestoreCommittedLogs is enabled, does a node that
// restarts on top of its persisted stores still recover the membership configuration
// that its own log already contains?
//
// api.go starts the startup configuration scan at max(snapshotIndex, lastApplied)+1.
// restoreFromCommittedLogs() sets lastApplied to the commit index read from the log
// store before that scan runs, so every configuration entry at an index <= that
// commit index is skipped even though it is present in the node's log.
//
// The harness builds real (bootstrap -> election -> client applies -> shutdown)
// single-voter prefixes on top of a commit-tracking log store, then restarts the node
// with the same stores and a fresh in-memory FSM, once with RestoreCommittedLogs on and
// once with it off, and reports the operands of the recovery.

type assuranceEvent map[string]interface{}

func assuranceEmit(ev assuranceEvent) {
	b, err := json.Marshal(ev)
	if err != nil {
		fmt.Println(`CA_EVENT {"event":"assurance.marshal_error"}`)
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

type assuranceStores struct {
	addr   ServerAddress
	local  ServerID
	conf   *Config
	logs   *InmemCommitTrackingStore
	stable *InmemStore
	snaps  *InmemSnapshotStore
}

func assuranceWaitElected(t *testing.T, r *Raft, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

// assuranceBuildPrefix runs the pre-restart life of one node and returns the stores it
// leaves behind. applyAfterSnapshot entries are applied after the optional snapshot, and
// the optional configuration change (AddNonvoter of a peer that never connects) is made
// after that snapshot as well, so the node has a committed configuration entry above its
// newest snapshot.
func assuranceBuildPrefix(t *testing.T, withSnapshot bool, caseName string) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	// The prefix must run with the feature enabled, otherwise no commit index is ever
	// staged into the log store and the restart has nothing to read.
	conf.RestoreCommittedLogs = true
	conf.TrailingLogs = 16

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}

	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}

	for i := 0; i < 4; i++ {
		if err := r.Apply([]byte(fmt.Sprintf("pre-%d", i)), 0).Error(); err != nil {
			t.Fatalf("prefix apply failed: %v", err)
		}
	}

	if withSnapshot {
		if err := r.Snapshot().Error(); err != nil {
			t.Fatalf("prefix snapshot failed: %v", err)
		}
		// A committed configuration entry strictly above the snapshot index.
		f := r.AddNonvoter(ServerID("assurance-peer-2"), ServerAddress("assurance-peer-2-addr"), 0, 2*time.Second)
		if err := f.Error(); err != nil {
			t.Fatalf("prefix AddNonvoter failed: %v", err)
		}
		for i := 0; i < 2; i++ {
			if err := r.Apply([]byte(fmt.Sprintf("post-%d", i)), 0).Error(); err != nil {
				t.Fatalf("prefix post apply failed: %v", err)
			}
		}
	}

	// Record the persisted state before shutdown.
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	configs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}
	snapIndex, snapTerm := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":                 "assurance.prefix",
		"case":                  caseName,
		"snapshot_present":      withSnapshot,
		"snapshot_index":        snapIndex,
		"snapshot_term":         snapTerm,
		"log_last_index":        lastIndex,
		"staged_commit_index":   stagedCommit,
		"config_entries":        configs.summary,
		"last_config_index":     configs.lastIndex,
		"last_config_voters":    configs.lastVoters,
		"last_config_nonvoters": configs.lastNonvoters,
		"recording_label_count": 0,
	})

	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

type assuranceConfigScan struct {
	summary       string
	lastIndex     uint64
	lastVoters    int
	lastNonvoters int
	lastIDs       []string
}

func assuranceLogConfigEntries(logs *InmemCommitTrackingStore, lastIndex uint64) (assuranceConfigScan, error) {
	out := assuranceConfigScan{summary: ""}
	for idx := uint64(1); idx <= lastIndex; idx++ {
		var entry Log
		if err := logs.GetLog(idx, &entry); err != nil {
			return out, err
		}
		switch entry.Type {
		case LogConfiguration:
			conf := DecodeConfiguration(entry.Data)
			voters, nonvoters := assuranceSuffrageCounts(conf)
			out.summary += fmt.Sprintf("LogConfiguration@%d(servers=%d,voters=%d)", idx, len(conf.Servers), voters)
			out.lastIndex = idx
			out.lastVoters = voters
			out.lastNonvoters = nonvoters
			out.lastIDs = assuranceSortedIDs(conf)
		case LogAddPeerDeprecated, LogRemovePeerDeprecated:
			out.summary += fmt.Sprintf("DeprecatedPeers@%d", idx)
			out.lastIndex = idx
		}
	}
	return out, nil
}

func assuranceSuffrageCounts(conf Configuration) (voters, nonvoters int) {
	for _, s := range conf.Servers {
		if s.Suffrage == Voter {
			voters++
		} else {
			nonvoters++
		}
	}
	return voters, nonvoters
}

func assuranceConfigIDs(conf Configuration) string {
	out := ""
	for i, s := range conf.Servers {
		if i > 0 {
			out += ","
		}
		out += string(s.ID)
	}
	return out
}

// assuranceSortedIDs returns a comparable, order independent list of server IDs.
func assuranceSortedIDs(conf Configuration) []string {
	out := make([]string, 0, len(conf.Servers))
	for _, s := range conf.Servers {
		out = append(out, string(s.ID))
	}
	sort.Strings(out)
	return out
}

// assuranceConfigurations asks the node's main thread for its current view of the
// tracked configurations, mirroring the pattern used by takeSnapshot.
func assuranceConfigurations(r *Raft) configurations {
	fut := &configurationsFuture{}
	fut.ShutdownCh = r.shutdownCh
	fut.init()
	select {
	case r.configurationsCh <- fut:
	case <-r.shutdownCh:
		return configurations{}
	}
	if err := fut.Error(); err != nil {
		return configurations{}
	}
	return fut.configurations
}

// assuranceRunCase restarts the node on top of the stored prefix and reports what the
// recovered node does with its configuration.
func assuranceRunCase(t *testing.T, caseName string, withSnapshot, restoreCommittedLogs bool) {
	t.Helper()

	stores := assuranceBuildPrefix(t, withSnapshot, caseName)
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	logConfigs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}

	// The fresh transport keeps the node's address (and therefore its ID) stable.
	_, trans := NewInmemTransport(stores.addr)
	conf := *stores.conf
	conf.RestoreCommittedLogs = restoreCommittedLogs

	assuranceEmit(assuranceEvent{
		"event":                   "assurance.restart." + caseName,
		"case":                    caseName,
		"restore_committed_logs":  restoreCommittedLogs,
		"snapshot_present":        withSnapshot,
		"log_last_index":          lastIndex,
		"staged_commit_index":     stagedCommit,
		"log_last_config_index":   logConfigs.lastIndex,
		"log_last_config_voters":  logConfigs.lastVoters,
		"log_last_config_servers": logConfigs.lastVoters + logConfigs.lastNonvoters,
	})

	r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		assuranceEmit(assuranceEvent{
			"event":                  "assurance.outcome." + caseName,
			"case":                   caseName,
			"restore_committed_logs": restoreCommittedLogs,
			"snapshot_present":       withSnapshot,
			"new_raft_error":         err.Error(),
		})
		return
	}

	// Observation window: 1.5s is 30 election/heartbeat timeouts of this in-memory
	// configuration (HeartbeatTimeout = ElectionTimeout = 50ms).
	deadline := time.Now().Add(1500 * time.Millisecond)
	leaderObserved := false
	polls := 0
	for time.Now().Before(deadline) {
		polls++
		if r.State() == Leader {
			leaderObserved = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}

	snapIndex, _ := r.getLastSnapshot()
	lastApplied := r.AppliedIndex()
	leaderAddr, leaderID := r.LeaderWithID()

	// Ask the main thread for the configuration the node is actually tracking.
	confs := assuranceConfigurations(r)
	latestVoters, latestNonvoters := assuranceSuffrageCounts(confs.latest)
	committedVoters, committedNonvoters := assuranceSuffrageCounts(confs.committed)
	latestIDs := assuranceSortedIDs(confs.latest)
	logIDs := logConfigs.lastIDs
	sameMembership := len(latestIDs) == len(logIDs)
	if sameMembership {
		for i := range latestIDs {
			if latestIDs[i] != logIDs[i] {
				sameMembership = false
				break
			}
		}
	}

	assuranceEmit(assuranceEvent{
		"event":                      "assurance.outcome." + caseName,
		"case":                       caseName,
		"restore_committed_logs":     restoreCommittedLogs,
		"snapshot_present":           withSnapshot,
		"leader_observed":            leaderObserved,
		"final_state":                r.State().String(),
		"polls":                      polls,
		"observation_ms":             1500,
		"leader_id":                  string(leaderID),
		"leader_addr":                string(leaderAddr),
		"latest_config_index":        confs.latestIndex,
		"committed_config_index":     confs.committedIndex,
		"latest_config_voters":       latestVoters,
		"latest_config_nonvoters":    latestNonvoters,
		"latest_config_ids":          assuranceConfigIDs(confs.latest),
		"committed_config_voters":    committedVoters,
		"committed_config_ids":       assuranceConfigIDs(confs.committed),
		"snapshot_index":             snapIndex,
		"last_applied":               lastApplied,
		"commit_index":               r.CommitIndex(),
		"last_index":                 r.LastIndex(),
		"committed_config_nonvoters": committedNonvoters,
	})

	// Does the recovered configuration equal the newest configuration entry in the
	// node's own log? Both operands are reported above; this flag is the comparison.
	matches := logConfigs.lastIndex != 0 &&
		sameMembership &&
		latestVoters == logConfigs.lastVoters &&
		latestNonvoters == logConfigs.lastNonvoters
	assuranceEmit(assuranceEvent{
		"event":                          "assurance.config_recovery." + caseName,
		"case":                           caseName,
		"restore_committed_logs":         restoreCommittedLogs,
		"snapshot_present":               withSnapshot,
		"log_last_config_index":          logConfigs.lastIndex,
		"log_last_config_voters":         logConfigs.lastVoters,
		"log_last_config_nonvoters":      logConfigs.lastNonvoters,
		"log_last_config_ids":            strings.Join(logConfigs.lastIDs, ","),
		"latest_config_index":            confs.latestIndex,
		"latest_config_voters":           latestVoters,
		"latest_config_nonvoters":        latestNonvoters,
		"latest_config_ids":              strings.Join(latestIDs, ","),
		"config_matches_last_log_config": matches,
	})

	_ = r.Shutdown().Error()
}

func TestAssuranceRestoreCommittedLogsConfigurationRecovery(t *testing.T) {
	assuranceRunCase(t, "no_snapshot_restore_on", false, true)
	assuranceRunCase(t, "no_snapshot_restore_off", false, false)
	assuranceRunCase(t, "snapshot_then_config_restore_on", true, true)
	assuranceRunCase(t, "snapshot_then_config_restore_off", true, false)
}

package raft

import (
	"encoding/json"
	"fmt"
	"runtime"
	"sort"
	"strings"
	"testing"
	"time"
)

// TestAssuranceRestoreCommittedLogsConfigurationRecovery
//
// Sourced question: when Config.RestoreCommittedLogs is enabled, does a node that
// restarts on top of its persisted stores still recover the membership configuration
// that its own log already contains?
//
// api.go starts the startup configuration scan at max(snapshotIndex, lastApplied)+1.
// restoreFromCommittedLogs() sets lastApplied to the commit index read from the log
// store before that scan runs, so every configuration entry at an index <= that
// commit index is skipped even though it is present in the node's log.
//
// The harness builds real (bootstrap -> election -> client applies -> shutdown)
// single-voter prefixes on top of a commit-tracking log store, then restarts the node
// with the same stores and a fresh in-memory FSM, once with RestoreCommittedLogs on and
// once with it off, and reports the operands of the recovery.

type assuranceEvent map[string]interface{}

func assuranceEmit(ev assuranceEvent) {
	b, err := json.Marshal(ev)
	if err != nil {
		fmt.Println(`CA_EVENT {"event":"assurance.marshal_error"}`)
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

type assuranceStores struct {
	addr   ServerAddress
	local  ServerID
	conf   *Config
	logs   *InmemCommitTrackingStore
	stable *InmemStore
	snaps  *InmemSnapshotStore
}

func assuranceWaitElected(t *testing.T, r *Raft, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

// assuranceBuildPrefix runs the pre-restart life of one node and returns the stores it
// leaves behind. applyAfterSnapshot entries are applied after the optional snapshot, and
// the optional configuration change (AddNonvoter of a peer that never connects) is made
// after that snapshot as well, so the node has a committed configuration entry above its
// newest snapshot.
func assuranceBuildPrefix(t *testing.T, withSnapshot bool, caseName string) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	// The prefix must run with the feature enabled, otherwise no commit index is ever
	// staged into the log store and the restart has nothing to read.
	conf.RestoreCommittedLogs = true
	conf.TrailingLogs = 16

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}

	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}

	for i := 0; i < 4; i++ {
		if err := r.Apply([]byte(fmt.Sprintf("pre-%d", i)), 0).Error(); err != nil {
			t.Fatalf("prefix apply failed: %v", err)
		}
	}

	if withSnapshot {
		if err := r.Snapshot().Error(); err != nil {
			t.Fatalf("prefix snapshot failed: %v", err)
		}
		// A committed configuration entry strictly above the snapshot index.
		f := r.AddNonvoter(ServerID("assurance-peer-2"), ServerAddress("assurance-peer-2-addr"), 0, 2*time.Second)
		if err := f.Error(); err != nil {
			t.Fatalf("prefix AddNonvoter failed: %v", err)
		}
		for i := 0; i < 2; i++ {
			if err := r.Apply([]byte(fmt.Sprintf("post-%d", i)), 0).Error(); err != nil {
				t.Fatalf("prefix post apply failed: %v", err)
			}
		}
	}

	// Record the persisted state before shutdown.
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	configs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}
	snapIndex, snapTerm := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":                 "assurance.prefix",
		"case":                  caseName,
		"snapshot_present":      withSnapshot,
		"snapshot_index":        snapIndex,
		"snapshot_term":         snapTerm,
		"log_last_index":        lastIndex,
		"staged_commit_index":   stagedCommit,
		"config_entries":        configs.summary,
		"last_config_index":     configs.lastIndex,
		"last_config_voters":    configs.lastVoters,
		"last_config_nonvoters": configs.lastNonvoters,
		"recording_label_count": 0,
	})

	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

type assuranceConfigScan struct {
	summary       string
	lastIndex     uint64
	lastVoters    int
	lastNonvoters int
	lastIDs       []string
}

func assuranceLogConfigEntries(logs *InmemCommitTrackingStore, lastIndex uint64) (assuranceConfigScan, error) {
	out := assuranceConfigScan{summary: ""}
	for idx := uint64(1); idx <= lastIndex; idx++ {
		var entry Log
		if err := logs.GetLog(idx, &entry); err != nil {
			return out, err
		}
		switch entry.Type {
		case LogConfiguration:
			conf := DecodeConfiguration(entry.Data)
			voters, nonvoters := assuranceSuffrageCounts(conf)
			out.summary += fmt.Sprintf("LogConfiguration@%d(servers=%d,voters=%d)", idx, len(conf.Servers), voters)
			out.lastIndex = idx
			out.lastVoters = voters
			out.lastNonvoters = nonvoters
			out.lastIDs = assuranceSortedIDs(conf)
		case LogAddPeerDeprecated, LogRemovePeerDeprecated:
			out.summary += fmt.Sprintf("DeprecatedPeers@%d", idx)
			out.lastIndex = idx
		}
	}
	return out, nil
}

func assuranceSuffrageCounts(conf Configuration) (voters, nonvoters int) {
	for _, s := range conf.Servers {
		if s.Suffrage == Voter {
			voters++
		} else {
			nonvoters++
		}
	}
	return voters, nonvoters
}

func assuranceConfigIDs(conf Configuration) string {
	out := ""
	for i, s := range conf.Servers {
		if i > 0 {
			out += ","
		}
		out += string(s.ID)
	}
	return out
}

// assuranceSortedIDs returns a comparable, order independent list of server IDs.
func assuranceSortedIDs(conf Configuration) []string {
	out := make([]string, 0, len(conf.Servers))
	for _, s := range conf.Servers {
		out = append(out, string(s.ID))
	}
	sort.Strings(out)
	return out
}

// assuranceConfigurations asks the node's main thread for its current view of the
// tracked configurations, mirroring the pattern used by takeSnapshot.
func assuranceConfigurations(r *Raft) configurations {
	fut := &configurationsFuture{}
	fut.ShutdownCh = r.shutdownCh
	fut.init()
	select {
	case r.configurationsCh <- fut:
	case <-r.shutdownCh:
		return configurations{}
	}
	if err := fut.Error(); err != nil {
		return configurations{}
	}
	return fut.configurations
}

// assuranceRunCase restarts the node on top of the stored prefix and reports what the
// recovered node does with its configuration.
func assuranceRunCase(t *testing.T, caseName string, withSnapshot, restoreCommittedLogs bool) {
	t.Helper()

	stores := assuranceBuildPrefix(t, withSnapshot, caseName)
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	logConfigs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}

	// The fresh transport keeps the node's address (and therefore its ID) stable.
	_, trans := NewInmemTransport(stores.addr)
	conf := *stores.conf
	conf.RestoreCommittedLogs = restoreCommittedLogs

	assuranceEmit(assuranceEvent{
		"event":                   "assurance.restart." + caseName,
		"case":                    caseName,
		"restore_committed_logs":  restoreCommittedLogs,
		"snapshot_present":        withSnapshot,
		"log_last_index":          lastIndex,
		"staged_commit_index":     stagedCommit,
		"log_last_config_index":   logConfigs.lastIndex,
		"log_last_config_voters":  logConfigs.lastVoters,
		"log_last_config_servers": logConfigs.lastVoters + logConfigs.lastNonvoters,
	})

	r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		assuranceEmit(assuranceEvent{
			"event":                  "assurance.outcome." + caseName,
			"case":                   caseName,
			"restore_committed_logs": restoreCommittedLogs,
			"snapshot_present":       withSnapshot,
			"new_raft_error":         err.Error(),
		})
		return
	}

	// Observation window: 1.5s is 30 election/heartbeat timeouts of this in-memory
	// configuration (HeartbeatTimeout = ElectionTimeout = 50ms).
	deadline := time.Now().Add(1500 * time.Millisecond)
	leaderObserved := false
	polls := 0
	for time.Now().Before(deadline) {
		polls++
		if r.State() == Leader {
			leaderObserved = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}

	snapIndex, _ := r.getLastSnapshot()
	lastApplied := r.AppliedIndex()
	leaderAddr, leaderID := r.LeaderWithID()

	// Ask the main thread for the configuration the node is actually tracking.
	confs := assuranceConfigurations(r)
	latestVoters, latestNonvoters := assuranceSuffrageCounts(confs.latest)
	committedVoters, committedNonvoters := assuranceSuffrageCounts(confs.committed)
	latestIDs := assuranceSortedIDs(confs.latest)
	logIDs := logConfigs.lastIDs
	sameMembership := len(latestIDs) == len(logIDs)
	if sameMembership {
		for i := range latestIDs {
			if latestIDs[i] != logIDs[i] {
				sameMembership = false
				break
			}
		}
	}

	assuranceEmit(assuranceEvent{
		"event":                      "assurance.outcome." + caseName,
		"case":                       caseName,
		"restore_committed_logs":     restoreCommittedLogs,
		"snapshot_present":           withSnapshot,
		"leader_observed":            leaderObserved,
		"final_state":                r.State().String(),
		"polls":                      polls,
		"observation_ms":             1500,
		"leader_id":                  string(leaderID),
		"leader_addr":                string(leaderAddr),
		"latest_config_index":        confs.latestIndex,
		"committed_config_index":     confs.committedIndex,
		"latest_config_voters":       latestVoters,
		"latest_config_nonvoters":    latestNonvoters,
		"latest_config_ids":          assuranceConfigIDs(confs.latest),
		"committed_config_voters":    committedVoters,
		"committed_config_ids":       assuranceConfigIDs(confs.committed),
		"snapshot_index":             snapIndex,
		"last_applied":               lastApplied,
		"commit_index":               r.CommitIndex(),
		"last_index":                 r.LastIndex(),
		"committed_config_nonvoters": committedNonvoters,
	})

	// Does the recovered configuration equal the newest configuration entry in the
	// node's own log? Both operands are reported above; this flag is the comparison.
	matches := logConfigs.lastIndex != 0 &&
		sameMembership &&
		latestVoters == logConfigs.lastVoters &&
		latestNonvoters == logConfigs.lastNonvoters
	assuranceEmit(assuranceEvent{
		"event":                          "assurance.config_recovery." + caseName,
		"case":                           caseName,
		"restore_committed_logs":         restoreCommittedLogs,
		"snapshot_present":               withSnapshot,
		"log_last_config_index":          logConfigs.lastIndex,
		"log_last_config_voters":         logConfigs.lastVoters,
		"log_last_config_nonvoters":      logConfigs.lastNonvoters,
		"log_last_config_ids":            strings.Join(logConfigs.lastIDs, ","),
		"latest_config_index":            confs.latestIndex,
		"latest_config_voters":           latestVoters,
		"latest_config_nonvoters":        latestNonvoters,
		"latest_config_ids":              strings.Join(latestIDs, ","),
		"config_matches_last_log_config": matches,
	})

	_ = r.Shutdown().Error()
}

func TestAssuranceRestoreCommittedLogsConfigurationRecovery(t *testing.T) {
	assuranceRunCase(t, "no_snapshot_restore_on", false, true)
	assuranceRunCase(t, "no_snapshot_restore_off", false, false)
	assuranceRunCase(t, "snapshot_then_config_restore_on", true, true)
	assuranceRunCase(t, "snapshot_then_config_restore_off", true, false)
}

// TestAssuranceRestoreCommittedLogsReplayCompletion
//
// Sourced question: does the startup replay performed by restoreFromCommittedLogs
// always complete? processLogs hands batches to the FSM through a buffered channel
// whose only consumer (runFSM) is started at the end of NewRaft, and the send has no
// timeout: it waits for buffer space or shutdown. So a replay that needs more batches
// than the channel can hold blocks inside NewRaft, before the consumer exists.
//
// The harness builds prefixes whose committed log is far above their (absent)
// snapshot, restarts them with and without RestoreCommittedLogs, and reports whether
// NewRaft returned and what the blocked goroutine was doing.

func assuranceBuildReplayPrefix(t *testing.T, caseName string, entries int) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	conf.RestoreCommittedLogs = true
	// Keep the whole committed log above the snapshot: no automatic snapshot is taken,
	// so a restart replays every committed entry from index 1.
	conf.SnapshotThreshold = 1 << 30
	conf.SnapshotInterval = time.Hour

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}
	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}
	for i := 0; i < entries; i++ {
		if err := r.Apply([]byte("x"), 0).Error(); err != nil {
			t.Fatalf("prefix apply %d failed: %v", i, err)
		}
	}
	staged, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	snapIndex, _ := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":               "assurance.replay_prefix",
		"case":                caseName,
		"commands_applied":    entries,
		"log_last_index":      lastIndex,
		"staged_commit_index": staged,
		"snapshot_index":      snapIndex,
		"max_append_entries":  conf.MaxAppendEntries,
		"replay_entries":      staged - snapIndex,
		"replay_batches":      (staged - snapIndex + uint64(conf.MaxAppendEntries) - 1) / uint64(conf.MaxAppendEntries),
	})
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

// assuranceStackExcerpt returns the goroutine block that mentions marker.
func assuranceStackExcerpt(text string, marker string) (string, int) {
	count := strings.Count(text, marker)
	if count == 0 {
		return "", 0
	}
	idx := strings.Index(text, marker)
	start := idx - 200
	if start < 0 {
		start = 0
	}
	end := idx + 300
	if end > len(text) {
		end = len(text)
	}
	excerpt := strings.ReplaceAll(text[start:end], "\n", " | ")
	return excerpt, count
}

type assuranceReplayResult struct {
	raft     *Raft
	err      error
	elapsed  int64
	returned bool
}

func assuranceRunReplayCase(t *testing.T, caseName string, restoreCommittedLogs bool, entries int) {
	t.Helper()

	stores := assuranceBuildReplayPrefix(t, caseName, entries)
	staged, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	_, trans := NewInmemTransport(stores.addr)
	conf := *stores.conf
	conf.RestoreCommittedLogs = restoreCommittedLogs

	assuranceEmit(assuranceEvent{
		"event":                  "assurance.replay_restart." + caseName,
		"case":                   caseName,
		"restore_committed_logs": restoreCommittedLogs,
		"staged_commit_index":    staged,
		"log_last_index":         lastIndex,
		"max_append_entries":     conf.MaxAppendEntries,
		"replay_entries":         staged,
	})

	const waitMS = 8000
	ch := make(chan assuranceReplayResult, 1)
	go func() {
		start := time.Now()
		r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
		ch <- assuranceReplayResult{raft: r, err: err, elapsed: time.Since(start).Milliseconds(), returned: true}
	}()

	var res assuranceReplayResult
	select {
	case res = <-ch:
	case <-time.After(waitMS * time.Millisecond):
	}

	outcome := assuranceEvent{
		"event":                  "assurance.replay_outcome." + caseName,
		"case":                   caseName,
		"restore_committed_logs": restoreCommittedLogs,
		"new_raft_returned":      res.returned,
		"wait_ms":                waitMS,
	}
	if res.returned {
		outcome["elapsed_ms"] = res.elapsed
	}
	if res.err != nil {
		outcome["new_raft_error"] = res.err.Error()
	}
	if !res.returned {
		buf := make([]byte, 1<<20)
		n := runtime.Stack(buf, true)
		excerpt, count := assuranceStackExcerpt(string(buf[:n]), "restoreFromCommittedLogs")
		outcome["stack_mentions"] = count
		outcome["blocked_excerpt"] = excerpt
	}
	assuranceEmit(outcome)

	if res.returned && res.raft != nil {
		leaderObserved := assuranceWaitElected(t, res.raft, time.Second)
		assuranceEmit(assuranceEvent{
			"event":                  "assurance.replay_leadership." + caseName,
			"case":                   caseName,
			"restore_committed_logs": restoreCommittedLogs,
			"leader_observed":        leaderObserved,
			"final_state":            res.raft.State().String(),
			"last_applied":           res.raft.AppliedIndex(),
			"commit_index":           res.raft.CommitIndex(),
		})
		_ = res.raft.Shutdown().Error()
	}
}

func TestAssuranceRestoreCommittedLogsReplayCompletion(t *testing.T) {
	const entries = 9000
	assuranceRunReplayCase(t, "large_replay_restore_on", true, entries)
	assuranceRunReplayCase(t, "large_replay_restore_off", false, entries)
}

