		"event":          "assurance.multi.start",
		"leader":         leader.name,
		"a_id":           string(a.id),
		"b_id":           string(b.id),
		"c_id":           string(c.id),
		"configured_ids": assuranceMultiSortedIDs(configuration),
	})

